-- Repair the legacy autogenerated payable snapshot check constraint.
-- The original table constraint was named srk_booking_payable_snapshots_check,
-- while migration 008 replaced only the later named total_amount_check.
-- Preserve unrounded labour and validate only the final paise-rounded total.
begin;

alter table public.srk_booking_payable_snapshots
  drop constraint if exists srk_booking_payable_snapshots_check;

alter table public.srk_booking_payable_snapshots
  drop constraint if exists srk_booking_payable_snapshots_total_amount_check;

alter table public.srk_booking_payable_snapshots
  add constraint srk_booking_payable_snapshots_total_amount_check
  check (total_amount = round(labour_amount + materials_amount, 2));

commit;
